pass('Co-tenant contacts and owner onboarding details persist without full tax IDs',()=>{const n=structuredClone(d);n.operations={...emptyOperations(),tenants:[{id:'co-tenant',unitId:n.units[0].id,firstName:'Demo',lastName:'One',email:'one@example.test',cell:'210-555-0101',secondFirstName:'Demo',secondLastName:'Two',secondCell:'210-555-0102',secondEmail:'two@example.test',specialInstructions:'Call before visiting',start:'2026-10-01',end:'',signedDate:'',rent:10000,opening:null,openingDate:'2026-10-01',notes:''}]};Object.assign(n.owners[0],{address:'Office mailing address',phone:'210-555-0100',paymentMethod:'ACH',taxIdType:'EIN',taxIdLast4:'1234',specialInstructions:'Pick up only with notice'});validate(d,n);assert.equal(JSON.parse(JSON.stringify(n)).operations.tenants[0].secondEmail,'two@example.test');const bad=structuredClone(n);bad.operations.tenants[0].secondEmail='bad';assert.throws(()=>validate(d,bad),/second tenant email/);const tax=structuredClone(n);tax.owners[0].taxIdLast4='123456789';assert.throws(()=>validate(d,tax),/last four/);});
await writeFile(join(tmpdir(), 'og-accounting-snapshot.json'),JSON.stringify(ownerFixture.n));await writeFile(join(tmpdir(), 'og-owner-package.zip'),new Uint8Array(await (await combinedOwnerPackage(ownerFixture.n,ownerFixture.other.ownerId,'2026-10',[])).arrayBuffer()));

const {parseQboPayments,importQboPayments}=await import(new URL('qbo-import.mjs',tmp));
const qboText=(amount='-600.00',ref='PAY-1')=>'Demo company\nInvoices and Received Payments (all)\nOctober 2026\n\n,Customer,Date,Transaction type,Transaction type id,Transaction number,Amount,Open balance,Open Balance\n,"#'+d.units[0].number+' - Sample, Tenant",10/02/2026,Payment,7,'+ref+','+amount+',,\n,"#'+d.units[0].number+' - Sample, Tenant",10/01/2026,Invoice,1,INV-1,1000.00,,\n';
const qboFixture=()=>{const n=structuredClone(d);n.operations=tenantFixture();n.operations.tenantEntries=[{...n.operations.tenantEntries[0],cents:100000,category:'Rent'}];return n;};
const qboSelect=(f,chargeId='',applyCents=0)=>[{sourceKey:f.payments[0].sourceKey,tenantId:'t1',method:'Not provided',chargeId,applyCents}];
pass('QBO report skips invoices, retains raw negative value and normalizes exact cents',()=>{const f=parseQboPayments(qboText());assert.equal(f.invoiceCount,1);assert.equal(f.payments[0].cents,60000);assert.equal(f.payments[0].originalAmount,'-600.00');assert.equal(f.payments[0].unitNumber,d.units[0].number);assert.equal(f.payments[0].number,'PAY-1');assert.equal(parseQboPayments(qboText('-0.01')).payments[0].cents,1);assert.ok(parseQboPayments(qboText('1.005')).payments[0].error);assert.throws(()=>parseQboPayments('Customer,Date'),/header/);});
pass('QBO receipt-only import persists provenance without changing owner statements or assumptions',()=>{const n=qboFixture(),f=parseQboPayments(qboText()),r=importQboPayments(n,f,'sample.csv','samplehash','2026-10',qboSelect(f));validate(n,r.data);assert.equal(r.data.operations.tenantEntries.at(-1).paymentMethod,'Not provided');assert.deepEqual(r.data.statements,n.statements);assert.deepEqual(r.data.settings,n.settings);assert.equal(officeRent(r.data,n.units[0].id,'2026-10').cents,0);validate(r.data,JSON.parse(JSON.stringify(r.data)));const edited=structuredClone(r.data);edited.qboImports[0].rows[0].source.raw[1]='Changed';assert.throws(()=>validate(r.data,edited),/Preserve QBO/);});
pass('QBO explicit rent matching advances partial to paid and actual collected totals',()=>{const n=qboFixture(),f=parseQboPayments(qboText()),r=importQboPayments(n,f,'sample.csv','samplehash','2026-10',qboSelect(f,'e1',60000));validate(n,r.data);assert.equal(chargeProgress(r.data,'e1').status,'Partially Paid');assert.equal(officeRent(r.data,n.units[0].id,'2026-10').cents,60000);const f2=parseQboPayments(qboText('-400.00','PAY-2')),r2=importQboPayments(r.data,f2,'second.csv','secondhash','2026-10',qboSelect(f2,'e1',40000));validate(r.data,r2.data);assert.equal(chargeProgress(r2.data,'e1').status,'Paid');assert.equal(officeRent(r2.data,n.units[0].id,'2026-10').cents,100000);assert.throws(()=>importQboPayments(r2.data,f,'repeat.csv','hash','2026-10',qboSelect(f)),/Duplicate/);const split=parseQboPayments(qboText('-300.00'));const splitResult=importQboPayments(r2.data,split,'split.csv','hash','2026-10',qboSelect(split));validate(r2.data,splitResult.data);assert.equal(splitResult.batch.rows[0].source.cents,30000);});
pass('QBO invalid month, tenant, method and excess matching reject atomically',()=>{const n=qboFixture(),f=parseQboPayments(qboText()),before=JSON.stringify(n);assert.throws(()=>importQboPayments(n,f,'sample.csv','hash','2026-11',qboSelect(f)));assert.throws(()=>importQboPayments(n,f,'sample.csv','hash','2026-10',[{...qboSelect(f)[0],tenantId:'unknown'}]));assert.throws(()=>importQboPayments(n,f,'sample.csv','hash','2026-10',[{...qboSelect(f)[0],method:'Cash'}]));assert.throws(()=>importQboPayments(n,f,'sample.csv','hash','2026-10',qboSelect(f,'e1',60001)));assert.equal(JSON.stringify(n),before);});
if(process.argv[2]){const sample=parseQboPayments(await readFile(process.argv[2],'utf8'));assert.equal(sample.payments.length,24);assert.equal(sample.invoiceCount,25);assert.equal(sample.payments.reduce((n,p)=>n+p.cents,0),2479500);assert.ok(sample.payments.every(p=>!p.error));console.log('PASS supplied QBO export: 24 payments, 25 invoices, $24,795.00');}
pass('PostgreSQL JSON field ordering preserves audit history through canonical cutover',()=>{const reorder=v=>Array.isArray(v)?v.map(reorder):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,reorder(v[k])])):v;const incoming=reorder(d);const canonical=v=>Array.isArray(v)?'['+v.map(canonical).join(',')+']':v&&typeof v==='object'?'{'+Object.keys(v).sort().map(k=>JSON.stringify(k)+':'+canonical(v[k])).join(',')+'}':JSON.stringify(v);assert.equal(canonical(incoming),canonical(d));validate(incoming,structuredClone(incoming));const removed=structuredClone(incoming);removed.audit.pop();assert.notEqual(canonical(removed),canonical(d));assert.throws(()=>validate(incoming,removed),/Audit/);const changed=structuredClone(incoming);changed.audit[0].action='changed';assert.notEqual(canonical(changed),canonical(d));assert.throws(()=>validate(incoming,changed),/Audit/);});
await rm(tmp,{recursive:true,force:true});console.log(tests+' checks passed');

